class Solution:
    def removeElement(self, nums: List[int], val: int) -> int:
        left = 0
        right = len(nums) - 1
        while left <= right:
            if nums[left] == val:
                nums[left] = nums[right]
                right -= 1
            else:
                left += 1
        return left

class Solution:
    def containsDuplicate(self, nums: List[int]) -> bool:
        maps={}
        for i in nums:
            if i in maps:
                return True
            maps[i]=True

        return False

class Solution:
    def licenseKeyFormatting(self, s: str, k: int) -> str:
        s = s.replace('-', '').upper()
        return '-'.join([s[max(i - k, 0):i] for i in range(len(s), 0, -k)][::-1])

class Solution:
    def detectCapitalUse(self, word: str) -> bool:
        a=word.lower()
        b=list(a)
        c=list(word)
        d=[]
        for i in range(len(b)):
           d.append(ord(b[i])-ord(c[i]))
        if d.count(0)==len(word):
            return True
        elif d.count(32) ==len(word):
            return True
        elif d.count(0) == (len(word)-1) and d.count(32)==1 and d[0]==32:
            return True
        else:
            return False

